\label{thm:local}
There exist constants $\eta_{\mathrm{loc}}>0,$
such that whenever
\[h\boldsymbol{\theta}  \in B(\mathbf{k}_1, \eta_{\mathrm{loc}})
\quad \text{or}\quad 
h\boldsymbol{\theta}  \in B(\mathbf{k}_2, \eta_{\mathrm{loc}})\]
we have
\begin{equation*}
|1-Z(h\boldsymbol{\theta})|\asymp  \rho_h(\boldsymbol{\theta}).
\end{equation*}

\label{rem:local}
We note that the conclusion of Theorem~\ref{thm:local} remains valid if the condition \(h\boldsymbol{\theta}  \in B(\mathbf{k}_1, \eta_{\mathrm{loc}})
\text{~or~}
h\boldsymbol{\theta}  \in B(\mathbf{k}_2, \eta_{\mathrm{loc}})\) is replaced by \(|1 - Z(h\boldsymbol{\theta})| \le \eta_{\mathrm{loc}}\).

\label{full}
For $\lambda \ge \frac{2}{3}$, the set
\[
D_\lambda := \left\{ \boldsymbol{\theta} \in \mathbb{T}^2\colon \boldsymbol{\theta} \text{ is of } \lambda\text{-Diophantine type} \right\}
\]
has full Lebesgue measure in \(\mathbb{T}^2\).

\label{FTK}
For \(z\ne1\),
\begin{equation*}
\mathcal{F}_N(z)
=\frac z{1-z}-\frac{z(1-z^N)}{N(1-z)^2}.
\end{equation*}
Moreover, uniformly for \(|z|\le1\),
\begin{equation*}

|\mathcal{F}_N(z)|
\ll
\min\left\{
N,\frac1{|1-z|}
\right\},

\end{equation*}
 with the convention that $\frac{1}{|1-z|} = +\infty$ when $z = 1$.

\label{smooth}
Let \(N\in\mathbb{N}\) be sufficiently large that \(1/N+1/N^2<\eta_{\mathrm{loc}}\). Then there exists a smooth cutoff function \(g_N\in C^\infty(\mathbb{T}^2)\) such that
\[
\left|
\frac{1}{N}
\sum_{h\in\mathbb{Z}}
\widehat{f}\!\left(\frac{h}{N}\right)
\mathbf{1}_N(h\boldsymbol{\theta})
\frac{Z(h\boldsymbol{\theta})^m}{1-Z(h\boldsymbol{\theta})}
-
\frac{1}{N}
\sum_{h\in\mathbb{Z}}
\widehat{f}\!\left(\frac{h}{N}\right)
g_N(h\boldsymbol{\theta})
\frac{Z(h\boldsymbol{\theta})^m}{1-Z(h\boldsymbol{\theta})}
\right|
\ll_M
N^{(1-1/\lambda)M+1/\lambda},
\]
where the implied constant depends on the parameter \(M\) governing the rapid decay of \(\widehat{f}\).

Let \(\psi \in C^\infty(\mathbb R)\) be a fixed function satisfying
\[
\psi(t) =
\begin{cases}
0, & t \le 0, \\
1, & t \ge 1,
\end{cases}
\quad \text{ and }
0 \le \psi(t) \le 1 \quad (t \in \mathbb R).
\]
Define
\begin{equation}\label{ap}
 g_N(\mathbf{x}) := \psi\!\left( \frac{N |1 - Z(\mathbf{x})| - 1}{1/N} \right)
= \psi\!\left( N^2 |1 - Z(\mathbf{x})| - N \right).   
\end{equation}
Then \(g_N \in C^\infty(\mathbb T^2)\) and
\[
g_N(\mathbf{x}) =
\begin{cases}
1, & |1 - Z(\mathbf{x})| \ge \dfrac{1}{N} + \dfrac{1}{N^2}, \\[6pt]
0, & |1 - Z(\mathbf{x})| \le \dfrac{1}{N} - \dfrac{1}{N^2},
\end{cases}
\]
with \(0 \le g_N \le 1\) everywhere. In the transition region
\[
T_N:=\left\{\mathbf{x}\in\mathbb{T}^{2}:\frac{1}{N}-\frac{1}{N^2}<|1-Z(\mathbf{x})|<\frac{1}{N}+\frac{1}{N^2}\right\},
\]
we have \(|g_N(\mathbf{x})-\mathbf{1}_N(\mathbf{x})|\le1\); outside this region, \(g_N(\mathbf{x})=\mathbf{1}_N(\mathbf{x})\).

Since \(1/N+1/N^2<\eta_{\mathrm{loc}}\), Remark~\ref{rem:local} implies that the difference between the sharp and smooth cutoffs is supported only in the transition region \(T_N\). Consequently,
\begin{align*}
&{}~~~~\left|
\frac{1}{N}
\sum_{h \in \mathbb Z}
\widehat f\!\left(\frac{h}{N}\right)
\mathbf{1}_N(h\boldsymbol{\theta})
\frac{Z(h\boldsymbol{\theta})^m}{1 - Z(h\boldsymbol{\theta})}
-
\frac{1}{N}
\sum_{h \in \mathbb Z}
\widehat f\!\left(\frac{h}{N}\right)
g_N(h\boldsymbol{\theta})
\frac{Z(h\boldsymbol{\theta})^m}{1 - Z(h\boldsymbol{\theta})}
\right|
\\
& = \frac{1}{N}
\left|
\sum_{h : h\boldsymbol{\theta} \in T_N}
\widehat f\!\left(\frac{h}{N}\right)
\Big(\mathbf{1}_N(h\boldsymbol{\theta})-g_N(h\boldsymbol{\theta})\Big)
\frac{Z(h\boldsymbol{\theta})^m}{1 - Z(h\boldsymbol{\theta})}
\right|
\\
&\ll_M
\frac{1}{N}
\sum_{h : |h| \gg N^{1/\lambda}}
\left( 1 + \frac{|h|}{N} \right)^{-M}
\cdot N
\ll_M
N^{(1 - 1/\lambda)M + 1/\lambda}.
\end{align*}

\label{Ab} We have 
\begin{equation*}
\lim_{N\to\infty}\int_{\mathbb{T}^{2}}\Phi_{N,m}(\mathbf{x})\,\mathrm{d} \mathbf{x}=0.
\end{equation*}

\label{0}
We have
\begin{equation*}

\lim_{N\to\infty}\frac1N
\sum_{h\in\mathbb Z}
\widehat f\left(\frac hN\right)
\Phi_{N,m}(h\boldsymbol{\theta})=0.

\end{equation*}
Removing the \(h=0\) term from the sum does not affect the limit.

\label{c1}
For \(N \in \mathbb{N}\) and  \(h_1, h_2 \in \mathbb{Z} \setminus \{0\}\), we have 
\[

\begin{aligned}
C_N(h_1, h_2)
&=
\sum_{S=1}^{N}
\biggl(
\sum_{R=1}^{S}
\bigl( z_{h_1-h_2}^{R} - z_{h_1}^{R} z_{-h_2}^{R} \bigr)
\biggr)
\biggl[
2  
\sum_{\substack{A, B \ge 1 \\ A + B \le N - S }}
z_{h_1}^{A} z_{-h_2}^{B}
\\
&\qquad \qquad \qquad \qquad 


+
\sum_{A=1}^{N-S}
(A + 1)(z_{h_1}^{A}+ z_{-h_2}^{A})+1
\biggr].
\end{aligned}

\]

\label{c2}
For \(N\in\mathbb{N}\) and \(h_1,h_2\in\mathbb{Z}\setminus\{0\}\), we have
\begin{equation*}
C_N(h_1,h_2)
=[t^N]\frac{1}{(1-t)^2}
\left(\frac{1}{1-z_{h_1-h_2}t}-\frac{1}{1-z_{h_1}z_{-h_2}t}\right)
\left(\frac{1}{1-z_{h_1}t}+\frac{1}{1-z_{-h_2}t}-1\right)^2.
\end{equation*}

Write
\begin{align*}
D_S
&:=
\sum_{R=1}^{S}
\bigl(z_{h_1-h_2}^{R}-z_{h_1}^{R}z_{-h_2}^{R}\bigr),\\
E_T
&:=
2\sum_{\substack{A,B\ge1\\ A+B\le T}}
z_{h_1}^{A}z_{-h_2}^{B}
+\sum_{A=1}^{T}(A+1)\bigl(z_{h_1}^{A}+z_{-h_2}^{A}\bigr)
+1.
\end{align*}
By Lemma~\ref{c1}, we obtain
\[
C_N(h_1,h_2)=\sum_{S=1}^{N}D_S E_{N-S}=\sum_{S=0}^{N}D_S E_{N-S},
\]
where the last equality uses \(D_0=0\). Thus the sequence \((C_N)\) is the convolution of the sequences \((D_S) \) and \((E_T) \). 
Consequently, the generating function of \((C_N)\) is the product of the generating functions of \((D_S)\) and \((E_T)\):
\begin{equation*}
\sum_{N=0}^{\infty}C_N(h_1,h_2)t^N
=
 \sum_{S=0}^{\infty}D_S t^S \cdot 
 \sum_{T=0}^{\infty}E_T t^T.
\end{equation*}
We now compute the two generating functions on the right-hand side.
Substituting the definition of \(D_S\) and interchanging the order of summation, we obtain
\[
\begin{aligned}
\sum_{S=0}^{\infty}D_S t^S
&=
\sum_{S=0}^{\infty}\sum_{R=1}^{S}
\bigl(z_{h_1-h_2}^{R}-z_{h_1}^{R}z_{-h_2}^{R}\bigr)t^S=
\sum_{R\ge1}
\bigl(z_{h_1-h_2}^{R}-z_{h_1}^{R}z_{-h_2}^{R}\bigr)
\sum_{S\ge R}t^S\\
&=
\sum_{R\ge1}
\bigl(z_{h_1-h_2}^{R}-z_{h_1}^{R}z_{-h_2}^{R}\bigr)\frac{t^R}{1-t}
=
\frac{1}{1-t}
\left(
\frac{1}{1-z_{h_1-h_2}t}
-
\frac{1}{1-z_{h_1}z_{-h_2}t}
\right).
\end{aligned}
\]
Using the identities
\begin{align*}
2\sum_{T\ge0}\sum_{\substack{A,B\ge1\\ A+B\le T}}
z_{1}^{A}z_{2}^{B}t^T
&=
\frac{2z_{1}z_{2}t^2}{(1-t)(1-z_{1}t)(1-z_{2}t)},\\
\sum_{T\ge0}\sum_{A=1}^{T}(A+1)z^{A}t^T
&=\frac{1}{1-t}\biggl(
\frac{1}{(1-zt)^2}-1\biggr),
\end{align*}
we directly compute the second generating function and obtain
\[
\sum_{T\ge0}E_T t^T
=
\frac{1}{1-t}
\left(
\frac{1}{1-z_{h_1}t}
+
\frac{1}{1-z_{-h_2}t}
-
1
\right)^2.
\]
Combining these completes the proof.

\label{XY}
Let \(X, Y \in \overline{\mathbb{D}}\). Then for   \(N\in\mathbb{N}\), the following statements hold.

\begin{enumerate}
\item[{(i)}] If \(X = Y\), then
\[
\left|
[t^N] \frac{1}{(1-t)^2(1-Xt)^2}
\right|
\ll
\frac{N}{(|1-X| + N^{-1})^2}.
\]

\item[(ii)]  If \(X\neq Y\), then, for some \(\xi\) lying on the segment \([X,Y]\),
\begin{align*}
&\left|
[t^N]\frac{1}{(1-t)^2(1-Xt)(1-Yt)}
\right|\\[6pt]
\ll~&
\min\left\{
\frac{N}{(|1-\xi|+N^{-1})^2},~
\frac{\frac{N}{|1-X|+N^{-1}}+\frac{N}{|1-Y|+N^{-1}}}{|X-Y|}
\right\}
+\frac{N}{|1-Y|+N^{-1}}.
\end{align*}


\item[(iii)] If 
 \(
|1-X| > N^{-r}\) and  \(|1-Y| > N^{-r} 
\) for \(r>0\),
then
\[
\left|
[t^N] \frac{1}{(1-t)^2(1-Xt)(1-Yt)}
\right|
\ll N^{1+5r}.
\]

\end{enumerate}

\label{XYY}
Let \(X,Y\in\overline{\mathbb D}\).  Then for \(N\in\mathbb{N}\),  the following statements hold.

\begin{enumerate}

\item[(i)] If \(X = Y\), then
\[
\left|
[t^N] \frac{1}{(1-t)^2(1-Xt)^3}
\right|
\ll
\frac{N}{|1-X|^3}+\frac{N^{2}}{|1-X|^{2}}.
\]


 \item[{(ii)}] If \(X \not=Y\), then
\begin{align*}
&\left|
[t^N] \frac{1}{(1-t)^2(1-Xt)(1-Yt)^{2}}
\right|
\\[6pt]
\ll~&
N \left[
\frac{(|1-X|+N^{-1})^{-1}+(|1-Y|+N^{-1})^{-1}}{|X-Y|^{2}}
+
\frac{(|1-Y|+N^{-1})^{-2}}{|X-Y|}
\right].
\end{align*}
\end{enumerate}

\label{c-d}
We have 
\[\left|C_N(h,h)\right|\ll \frac{N^{2}}{|1-z_h|^{2}}.\]

\label{diag}
Let \(s \in \mathbb{N}\). For \(N\) sufficiently large that \((1/N)^{1/8}<\eta_{\mathrm{loc}}\), where \(\eta_{\mathrm{loc}}>0\) is the constant from Theorem~\ref{thm:local}, we have
\[\frac{1}{N^2}
\sum_{h \in \mathbb Z \setminus \{0\}}
\left| \widehat f\!\left(\frac{h}{N}\right) \right|^s
\cdot
\frac{1}{|1 - z_h|^2}\ll N^{-\frac{1}{3}}\]

For $0<\varepsilon <{1}/{18},$  we fix $\lambda= {2}/{3}+\varepsilon$ and  
\(M \ge (2\lambda(1+\varepsilon) + 1/3)/\varepsilon.\) 

As in the expectation estimate in the previous section, we split the relevant sum into two parts, one over the near-exceptional set and the other over the regular set. Here the definitions of these two sets are slightly different from those used before; the near-exceptional set and the regular set are defined respectively by
\[
\Omega_N^{(1)}
:=
\left\{
h \in \mathbb Z \setminus \{0\} : |1 - z_h| < \frac{1}{N^{1/8}}
\right\}~~\text{and } ~\Omega_N^{(2)}
:=
\left\{
h \in \mathbb Z \setminus \{0\} : |1 - z_h| \ge \frac{1}{N^{1/8}}
\right\}.
\]
We then have
\[\frac{1}{N^2}
\sum_{h \in \mathbb Z \setminus \{0\}}
\left| \widehat f\!\left(\frac{h}{N}\right) \right|^2
\cdot
\frac{1}{|1 - z_h|^2}
=
\frac{1}{N^2}
\sum_{h \in \Omega_N^{(1)}}
+
\frac{1}{N^2}
\sum_{h \in \Omega_N^{(2)}}
=:
S_{1,N}
+S_{2,N}.
\]



























\paragraph{Estimate of $S_{1,N}$.}  By Theorem \ref{thm:local} and Remark \ref{rem:local},  we obtain 
\[S_{1,N}\asymp\frac{1}{N^2}
\sum_{h \in \Omega_N^{(1)}}
\left| \widehat f\!\left(\frac{h}{N}\right) \right|^s
\cdot
\frac{1}{\rho_h(\boldsymbol{\theta})^2}.\]
Splitting the sum according to \(|h| \le N^{1+\varepsilon}\) and \(|h| > N^{1+\varepsilon}\), we obtain
\begin{align*}
S_{1,N}
&\ll_{\boldsymbol{\theta}}
\frac{1}{N^2}
\sum_{\substack{h \in \Omega_N^{(1)} \\ 0 < |h| \le N^{1+\varepsilon}}}
\left|\widehat f\!\left(\frac{h}{N}\right) \right|^s
\cdot
\frac{1}{\rho_h(\boldsymbol{\theta})^2}
+
\frac{1}{N^2}
\sum_{\substack{h \in \Omega_N^{(1)} \\ |h| > N^{1+\varepsilon}}}
\left(1 + \frac{|h|}{N}\right)^{-sM}
|h|^{2\lambda}\\
&\ll_{\boldsymbol{\theta},M}
\frac{1}{N^2}
\sum_{\substack{h \in \Omega_N^{(1)} \\ 0 < |h| \le N^{1+\varepsilon}}}
\left|\widehat f\!\left(\frac{h}{N}\right) \right|^s
\cdot
\frac{1}{\rho_h(\boldsymbol{\theta})^2}+N^{-sM\varepsilon+2\lambda(1+\varepsilon)}\\
&\le\frac{1}{N^2} \sum_{j=0}^{\left\lceil (1+\varepsilon)\log N \right\rceil} \sum_{2^{j}\le |h|<2^{j+1}}\frac{\mathbf{1}_{\{h\colon \rho_h(\boldsymbol{\theta})\ll \frac{1}{N} \}}}{\rho_h(\boldsymbol{\theta})^2}+N^{-sM\varepsilon+2\lambda(1+\varepsilon)}.\end{align*}
It remains to control the contribution from the first sum.
For $k\in\mathbb{N},$ we define 
\[\mathcal B_{j,k}:=\{h\in\mathbb{Z}\colon 2^{j}\le |h|<2^{j+1}, 2^{-(k+1)}\le\rho_h(\boldsymbol{\theta})<2^{-k} \}.\]
Since $\rho_h(\boldsymbol{\theta})\gg|h|^{-\lambda}$ and  $2^{-j\lambda}\ll2^{-k}\ll (\frac{1}{N})^{1/8}$,  
\begin{align*}
\sum_{2^{j}\le |h|<2^{j+1}}\frac{\mathbf{1}_{\{h\colon \rho_h(\boldsymbol{\theta})\ll \frac{1}{N} \}}}{\rho_h(\boldsymbol{\theta})^2}\asymp\sum_{k: 2^{-j\lambda}\ll2^{-k}\ll (\frac{1}{N})^{1/8}}~\sum_{h\in \mathcal B_{j,k}}2^{2k}
=\sum_{k: 2^{-j\lambda}\ll2^{-k}\ll (\frac{1}{N})^{1/8}} \# \mathcal B_{j,k}\cdot 2^{2k}.
    \end{align*}

A key observation is the following: for  \(h_1, h_2 \in \mathcal B_{j,k}\) with \(h_1 \neq h_2\),                                                          
\[
|h_1 - h_2|^{-\lambda}
\ll \rho_{h_1 - h_2}(\boldsymbol{\theta})
\ll \rho_{h_1}(\boldsymbol{\theta}) + \rho_{h_2}(\boldsymbol{\theta})
< 2^{-(k-1)}.
\]
Indeed, the first inequality follows from the Diophantine condition, the second from the triangle inequality for \(\rho_h\), and the third from the defining property of \(\mathcal B_{j,k}\). 

Consequently,
\[
|h_1 - h_2| \gg 2^{k/\lambda},
\]
which implies that the elements of \(\mathcal B_{j,k}\) are separated by at least a distance of order \(2^{k/\lambda}\). Since \(\mathcal B_{j,k} \subset [-2^{j+1}, 2^{j+1}]\), we obtain
\[
\#  \mathcal B_{j,k}
\ll
\frac{2^{j}}{2^{k/\lambda}}+1.
\]
It follows that 
\begin{align*}
\sum_{2^{j}\le |h|<2^{j+1}}\frac{\mathbf{1}_{\{h\colon \rho_h(\boldsymbol{\theta})\ll \frac{1}{N} \}}}{\rho_h(\boldsymbol{\theta})^2}
\ll \sum_{k: 2^{-j\lambda}\ll2^{-k}\ll (\frac{1}{N})^{1/8}}  2^{2k}(\frac{2^{j}}{2^{k/\lambda}}+1)\asymp2^{2j\lambda} .
    \end{align*}

 Therefore we conclude that
\[S_{1,N}\ll_{\boldsymbol{\theta},M}\frac{1}{N^2} \sum_{j=0}^{\left\lceil (1+\varepsilon)\log N \right\rceil} 2^{2j\lambda}+ N^{-sM\varepsilon+2\lambda(1+\varepsilon)}\ll N^{-2+2\lambda(1+\varepsilon)}+N^{-sM\varepsilon+2\lambda(1+\varepsilon)}\ll N^{-\frac{1}{3}}.\]





\paragraph{Estimate of $S_{2,N}$.} We deduce that 
\begin{align*}
S_{2,N}
\le \frac{1}{N^{2}}\left(\sum_{1\le |h|<N^{1+\varepsilon}} N^{\frac{1}{4}}+\sum_{ |h|\ge N^{1+\varepsilon}} (1+\frac{|h|}{N})^{-2M}N^{\frac{1}{4}}\right)\ll N^{-\frac{1}{3}}.
\end{align*}

\label{var:og}
For sufficiently large $N$, we have
\[\operatorname{Var}^{\mathrm{off}}_{\mathcal G}(R_N(f))\ll N^{-1+12r}.\]

\label{var:2-2}
We have 
\[S_N\ll N^{-\min\{{r}/{2}-8\varepsilon, \, {2}/{3}-3\varepsilon\}}.\]

We deduce that
\begin{align*}
S_N
&\le
\frac{1}{N^2}
\sum_{\substack{(h_1, h_2) \in \mathcal B_N \\ 1 \le |h_1|, |h_2| \le N^{1+\varepsilon}}}
\frac{|v_1 v_2|}{v_1^2 + v_2^2 + N^{-1}}
\frac{1}{|1 - z_{h_1}|^2}
\\
&\ll
\frac{1}{N^2}
\sum_{\substack{(h_1, h_2) \in \mathcal B_N \\ 1 \le |h_1|, |h_2| \le N^{1+\varepsilon}}}
\frac{|v_1 v_2|}{v_1^2 + v_2^2 + N^{-1}}
\frac{1}{\rho_{h_1}(\boldsymbol{\theta})^2},
\end{align*}
where the second step uses \(\rho_{h_1}(\boldsymbol{\theta}) \asymp |1 - z_{h_1}|\) (Theorem~\ref{thm:local}).

We now decompose the sum into dyadic layers according to
\[
\rho_{h_i}(\boldsymbol{\theta}) \asymp 2^{-l_i},
\quad 
v_i^2 \asymp 2^{-k_i},
\quad i = 1, 2,
\]
with the ranges
\[
N^{-\lambda} \ll 2^{-l_i} \ll N^{-r},
\quad 
2^{-k_i} \ll 2^{-l_i}.
\]
Thus
\begin{align*}
S_N
&\ll
\frac{1}{N^2}
\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_i}}}
\#  \Omega_{k_1, l_1}^{(1)}
\cdot
\#  \Omega_{k_2, l_2}^{(2)}
\cdot
\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
\cdot
2^{2 l_1}.
\end{align*}

By Lemma~\ref{Omega-b}, the cardinalities satisfy
\[
\#  \Omega_{k_i, l_i}^{(i)}
\ll
\min\left\{
1 + \frac{N^{1+\varepsilon}}{2^{l_i/\lambda}},
\left(1 + \frac{2^{-l_i}}{N^{-\lambda(1+\varepsilon)}}\right)
\left(1 + \frac{2^{-k_i/2}}{N^{-\lambda(1+\varepsilon)/2}}\right)
\right\}.
\]
Substituting these bounds into the above expression yields
\begin{align*}
S_N
&\ll
\frac{1}{N^2}
\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll N^{-r}}}
\left(1 + \frac{N^{1+\varepsilon}}{2^{l_1/\lambda}}\right)
\\
&\quad \quad 
\times
\left(1 + \frac{2^{-l_2}}{N^{-\lambda(1+\varepsilon)}}\right)
\left(1 + \frac{2^{-k_2/2}}{N^{-\lambda(1+\varepsilon)/2}}\right)
\cdot
\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
\cdot
2^{2 l_1}.
\end{align*}
Expanding the product of the three brackets, we obtain a sum of \(2\times2\times2=8\) terms. We estimate each term separately. We list the eight terms in increasing binary order, where the first bracket corresponds to the least significant bit.
\medskip

\noindent \textbf{Term 1.} We now estimate the first term \(S_{N,1}\): 

\begin{align*}
S_{N,1}
&:=
\frac{1}{N^2}
\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_i}}}
\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
\cdot
2^{2 l_1}.
\end{align*}

We first sum over \(l_1\) and \(l_2\). Since the range of each \(l_i\) has length \(\asymp \log N\) and the summand depends only on \(l_1\), we have
\[
\sum_{l_1} 2^{2 l_1} \asymp N^{2\lambda}.
\]
 The sum over \(l_2\) contributes a factor \(\asymp \log N\). Hence
\[
\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}} 2^{2 l_1} \asymp N^{2\lambda} \log N.
\]
Substituting this into \(S_{N,1}\) and extracting the factor \(N^{-2}\), we obtain
\begin{align*}
S_{N,1}
&\asymp
\frac{\log N}{N^{2-2\lambda}}
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_i}}}
\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}.
\end{align*}
It remains to estimate the sum over \(k_1, k_2\), which we shall do below.


\medskip
\noindent\textbf{Sublemma 1.}
\[
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_i}}}
\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
\ll (\log N)^{2}.
\]

\begin{proof}
We split the sum into three cases according to whether both, exactly one, or neither of \(2^{-k_1}, 2^{-k_2}\) exceeds \(N^{-1}\).

\medskip
\noindent{Case 1:} \(2^{-k_1} > N^{-1}\) and \(2^{-k_2} > N^{-1}\).

In this case, the elementary inequality
\(
(ab)^{1/2} \le a + b
\)
gives
\[
\sum_{\substack{k_1, k_2 \\ N^{-1}<2^{-k_i} \ll 2^{-l_i} }}
\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
\ll
\sum_{k_1 \asymp \log N} \sum_{k_2 \asymp \log N} 1
\asymp (\log N)^{2},
\]
where \(k_2 \asymp \log N\) since
\(N^{-1} < 2^{-k_i} \ll 2^{-l_i} \ll N^{-r}.\)



\medskip
\noindent{Case 2:} exactly one of \(2^{-k_1}, 2^{-k_2}\) is \(> N^{-1}\).

Without loss of generality, assume \(2^{-k_1} > N^{-1}\).
\[\sum_{k_1: N^{-1}<2^{-k_1}\ll 2^{-l_1}}~ \sum_{k_2: 2^{-k_2}<N^{-1}} \frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}} \le \sum_{k_1: N^{-1}<2^{-k_1}\ll N^{-r}}~ \sum_{k_2: 2^{-k_2}<N^{-1}}  2^{k_1/2}2^{-k_2/2}\asymp 1.\]


\medskip
\noindent{Case 3:} \(2^{-k_1}  \le  N^{-1}\) and \(2^{-k_2} \le  N^{-1}\).
\[\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \le N^{-1} }}\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}} \le N \sum_{\substack{k_1, k_2 \\ 2^{-k_i} \le N^{-1} }} (2^{-k_1} 2^{-k_2})^{1/2} \asymp 1. \]
\end{proof}


Thus, by  {Sublemma 1}, 
\[S_{N,1}\ll \frac{(\log N)^{3}}{N^{2-2\lambda}}.\]


\noindent \textbf{Term 2.} We estimate  
\begin{align*}
 S_{N,2}:=\frac{1}{N^2}
\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}}
\frac{N^{1+\varepsilon}}{2^{l_1/\lambda}}\cdot\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
\cdot
2^{2 l_1}.
\end{align*}
Since \(\lambda = 2/3 + \varepsilon > 1/2\), we have \(2 - 1/\lambda > 0\), and
\[
\sum_{l_1: N^{-\lambda} \ll 2^{-l_1} \ll N^{-r}} N^{1+\varepsilon} 2^{l_1(2 - 1/\lambda)}
\asymp
N^{1+\varepsilon} \cdot N^{2\lambda - 1}
=
N^{2\lambda + \varepsilon}.
\]
The sum over \(l_2\) contributes a factor \(\asymp \log N\), and by  {Sublemma 1},
\[
S_{N,2}
\ll
\frac{1}{N^2}
\cdot
N^{2\lambda + \varepsilon}
\cdot
\log N
\cdot
(\log N)^{2}
=
\frac{(\log N)^3}{N^{2 - 2\lambda - \varepsilon}}.
\]



\noindent \textbf{Term 3.} By {Sublemma 1}, we have 
\begin{align*}
 S_{N,3}&:=\frac{1}{N^2}
\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}}
\frac{2^{-l_2}}{N^{-\lambda(1+\varepsilon)}}\cdot\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
\cdot
2^{2 l_1}\\
&\ll \frac{(\log N)^{2}}{N^{2+r-3\lambda-\lambda\varepsilon}}.
\end{align*}




\noindent \textbf{Term 4.} By {Sublemma 1}, we have
\begin{align*}
