\medskip
\noindent\textbf{Sublemma 2.}
\[
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}}
\frac{2^{-k_1/2} 2^{-k_2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
