\]

\begin{proof}

As before, we split the sum into three cases.                                                                                                  

\medskip
\noindent{Case 1:} \(2^{-k_1}> N^{-1}\) and \(2^{-k_2} > N^{-1}\).
We deduce 
\begin{align*}
  \sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}}
\frac{2^{-k_1/2} 2^{-k_2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}
&\le \sum_{\substack{k_1\le k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}}
\frac{2^{-k_1/2} 2^{-k_2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}+\sum_{\substack{k_1\ge k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}}
\frac{2^{-k_1/2} 2^{-k_2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}\\
&\ll \sum_{\substack{k_1\le k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}} 2^{k_1/2}2^{-k_2}+\sum_{\substack{k_1\ge k_2 \\ 2^{-k_i} \ll 2^{-l_{1}}}}2^{-k_1/2}\\
&\asymp\sum_{k_1: 2^{-k_1} \ll 2^{-l_{1}}}2^{-k_1/2}+\log N\sum_{k_1: 2^{-k_1} \ll 2^{-l_{1}}}2^{-k_1/2}\\
&\asymp2^{-l_1/2}\log N.
\end{align*}


\medskip
\noindent{Case 2}: exactly one of \(2^{-k_1}, 2^{-k_2}\) is \(> N^{-1}\).
If \(2^{-k_1} > N^{-1} \ge 2^{-k_2}\), then \(k_1 < k_2\); if \(2^{-k_2} > N^{-1} \ge 2^{-k_1}\), then \(k_1 \ge k_2\). In either subcase, the argument as for Case 1 gives the summation is
\(
\ll 2^{-l_1/2} \log N.
\)


\medskip
\noindent{Case 3:} \(2^{-k_1}\le N^{-1}\) and \(2^{-k_2} \le N^{-1}\).

A direct calculation gives
\[\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \le N^{-1}}}
