2^{-k_1/2} 2^{-k_2}\asymp N^{-1/2}.\]
\end{proof}



Hence, by {Sublemma 2}, we have
\begin{align*}
    S_{N,7}&\ll \frac{N^{\frac{3\lambda}{2}(1+\varepsilon)}\log N}{N^2}\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}
\frac{(2^{-l_1/2}+N^{-1})2^{2l_1}}{2^{l_2}}\\
& \ll \frac{N^{\frac{3\lambda}{2}(1+\varepsilon)}\log N}{N^2}N^{-r}\cdot (N^{3\lambda/2}+N^{2\lambda-1})\\
&\ll \frac{\log N}{N^{2+r-3\lambda(1+\varepsilon)}}.
\end{align*}





\noindent \textbf{Term 8.}  {Sublemma 2} gives
\begin{align*}
