\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}
\sum_{\substack{k_1, k_2 \\ 2^{-k_i} \ll 2^{-l_{i}}}}
\frac{N^{(1+\frac{3\lambda}{2})(1+\varepsilon)}}{2^{l_1/\lambda}2^{k_2/2}2^{l_2}}\cdot\frac{(2^{-k_1} 2^{-k_2})^{1/2}}{2^{-k_1} + 2^{-k_2} + N^{-1}}\cdot 2^{2l_1}\\
&\ll \frac{N^{(1+\frac{3\lambda}{2})(1+\varepsilon)}\log N}{N^2}\sum_{\substack{l_1, l_2 \\ N^{-\lambda} \ll 2^{-l_i} \ll N^{-r}}}\frac{(2^{-l_1/2}+N^{-1})2^{2l_1}}{2^{l_1/\lambda}2^{l_2}}\\
&\ll \frac{N^{(1+\frac{3\lambda}{2})(1+\varepsilon)}\log N}{N^{2+r}}\sum_{l_1: N^{-\lambda} \ll 2^{-l_1} \ll N^{-r}}(2^{l_1(\frac{3}{2}-\frac{1}{\lambda})}+N^{-1}2^{l_1(2-\frac{1}{\lambda})})\\
&\ll \frac{N^{(1+\frac{3\lambda}{2})(1+\varepsilon)}\log N}{N^{2+r}}N^{\frac{3\lambda}{2}-1}=\frac{\log N}{N^{2+r-3\lambda-(1+\frac{3\lambda}{2})\varepsilon}}.
\end{align*}

To conclude, since  $\lambda=2/3+\varepsilon,$ we have
\[S_N=S_{N,1}+\cdots+S_{N,8}\ll N^{-\min\{ {r}/{2}-8\varepsilon, \, {2}/{3}-3\varepsilon\}}.\]

As before, we split the sum into three cases.                                                                                                  

\medskip
\noindent{Case 1:} \(2^{-k_1}> N^{-1}\) and \(2^{-k_2} > N^{-1}\).
